/* ---------- الفحوص الأولية الحتمية ---------- */
const NATURE_AR = {debit:"مدين",credit:"دائن"};

/* ---------- تطبيع النصوص والأرقام العربية ---------- */
function toWesternDigits(s){
  return String(s)
    .replace(/[\u0660-\u0669]/g,d=>String(d.charCodeAt(0)-0x0660))
    .replace(/[\u06F0-\u06F9]/g,d=>String(d.charCodeAt(0)-0x06F0));
}
function normalizeAr(s){
  if(s==null) return "";
  let t=String(s).toLowerCase();
  t=toWesternDigits(t);
  t=t.replace(/[\u064B-\u0652\u0670\u0640]/g,"");      // تشكيل وتطويل
  t=t.replace(/[أإآٱ]/g,"ا").replace(/ة/g,"ه").replace(/ى/g,"ي").replace(/ؤ/g,"و").replace(/ئ/g,"ي");
  t=t.replace(/[^\u0600-\u06FFa-z0-9\s]/g," ");
  t=t.replace(/\s+/g," ").trim();
  return t;
}
function parseAmount(v){
  if(v==null) return 0;
  if(typeof v==="number") return isFinite(v)?v:0;
  let s=toWesternDigits(String(v).trim());
  if(!s) return 0;
  let neg=false;
  if(/^\(.*\)$/.test(s)){neg=true;s=s.slice(1,-1);}
  if(/^-/.test(s)){neg=true;s=s.slice(1);}
  if(/-\s*$/.test(s)){neg=true;s=s.replace(/-\s*$/,"");}
  s=s.replace(/٫/g,".").replace(/[٬,\s\u00A0']/g,"");
  s=s.replace(/[^0-9.]/g,"");
  if(!s||s===".") return 0;
  const n=parseFloat(s);
  return isFinite(n)?(neg?-n:n):0;
}
const _nf=new Intl.NumberFormat("en-US",{maximumFractionDigits:2});
function fmt(n){ if(n==null||isNaN(n)) return "—"; return _nf.format(Math.round(n*100)/100); }
function escapeHtml(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;"); }

/* تجهيز قواعد التصنيف: مطابقة على حدود الكلمة مع قبول سوابق «و/ال/ب/ل/ك» */
const AR_LET="\\u0600-\\u06FFa-z0-9";
function kwToRe(k){
  const words=normalizeAr(k).split(" ").filter(Boolean).map(w=>{
    let core=w;
    if(core.startsWith("ال")&&core.length>=5) core=core.slice(2);
    core=core.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
    return "(?:[ولبكف])?(?:ال)?"+core;
  });
  return new RegExp("(?:^|[^"+AR_LET+"])"+words.join("\\s+")+"(?![" + AR_LET + "])");
}
RULES.forEach(r=>{ r.kwR=r.kw.map(kwToRe); r.exR=(r.ex||[]).map(kwToRe); });

function classifyAccount(name){
  const n=normalizeAr(name);
  if(!n) return null;
  for(const r of RULES){
    if(r.exR.length && r.exR.some(x=>x.test(n))) continue;
    if(r.kwR.some(k=>k.test(n))) return r;
  }
  return null;
}

/* ---------- قراءة ميزان المراجعة ---------- */
function splitLine(line,d){
  if(d==="\t") return line.split("\t");
  const out=[]; let cur="",q=false;
  for(let i=0;i<line.length;i++){
    const c=line[i];
    if(c==='"'){ if(q&&line[i+1]==='"'){cur+='"';i++;} else q=!q; }
    else if(c===d && !q){ out.push(cur); cur=""; }
    else cur+=c;
  }
  out.push(cur);
  return out;
}
function parseTable(text){
  const lines=String(text||"").replace(/\r/g,"").split("\n").filter(l=>l.trim()!=="");
  if(!lines.length) return null;
  const probe=lines.slice(0,5).join("\n");
  let delim="\t";
  if(probe.indexOf("\t")===-1){
    const c=(probe.match(/,/g)||[]).length, s=(probe.match(/;/g)||[]).length, p=(probe.match(/\|/g)||[]).length;
    delim = p>c&&p>s ? "|" : (s>c ? ";" : ",");
    if(c===0&&s===0&&p===0){
      const rows=lines.map(l=>l.trim().split(/\s{2,}/));
      return {headers:rows[0].map(x=>x.trim()), rows:rows.slice(1)};
    }
  }
  const rows=lines.map(l=>splitLine(l,delim).map(x=>x.trim()));
  return {headers:rows[0], rows:rows.slice(1)};
}
function guessColumns(headers){
  const H=headers.map(normalizeAr);
  const used=new Set();
  const find=(keys)=>{ for(const k of keys){ for(let i=0;i<H.length;i++){ if(!used.has(i)&&H[i].includes(k)){ used.add(i); return i; } } } return -1; };
  const code=find(["رقم","كود","رمز","code"]);
  const name=find(["اسم","بيان","وصف","name","حساب","account"]);
  const debit=find(["مدين","debit"]);
  const credit=find(["داين","دائن","credit"]);
  const balance=find(["رصيد","صافي","balance","net"]);
  return {code,name,debit,credit,balance};
}
function buildTB(table,map){
  const accs=[]; let auto=1;
  for(const row of table.rows){
    const name=(map.name>-1?row[map.name]:"")||"";
    const nn=normalizeAr(name);
    if(!nn) continue;
    if(/^(ال)?(اجمالي|اجمالى|مجموع|المجموع|صافي الميزان|total|grand total)\b/.test(nn)) continue;
    let debit=0,credit=0;
    if(map.debit>-1||map.credit>-1){
      debit=map.debit>-1?parseAmount(row[map.debit]):0;
      credit=map.credit>-1?parseAmount(row[map.credit]):0;
      if(debit<0){credit+=-debit;debit=0;}
      if(credit<0){debit+=-credit;credit=0;}
    }else if(map.balance>-1){
      const b=parseAmount(row[map.balance]);
      if(b>=0)debit=b;else credit=-b;
    }
    if(debit===0&&credit===0&&!/^[0-9]/.test(nn)&&accs.length===0) continue;
    const code=map.code>-1?toWesternDigits(String(row[map.code]||"")).trim():String(auto++);
    const rule=classifyAccount(name);
    accs.push({code,name,debit,credit,net:debit-credit,ruleId:rule?rule.id:null});
  }
  return accs;
}
function ruleById(id){ return RULES.find(r=>r.id===id)||null; }
function tbTotals(accs){
  let dr=0,cr=0;
  accs.forEach(a=>{dr+=a.debit;cr+=a.credit;});
  return {dr,cr,diff:dr-cr};
}
function sumBy(accs,fn){ let s=0; accs.forEach(a=>{s+=fn(a)||0;}); return s; }

/* ---------- الأهمية النسبية (ISA 320) ---------- */
const MAT_BASES={revenue:"إجمالي الإيرادات",assets:"إجمالي الأصول",equity:"حقوق الملكية",profit:"صافي الربح قبل الزكاة"};
function computeMateriality(accs,basis,pct){
  const cat=id=>{const r=ruleById(id);return r?r.st:null;};
  const rev=sumBy(accs,a=>cat(a.ruleId)==="PL-R"?-a.net:0);
  const exp=sumBy(accs,a=>cat(a.ruleId)==="PL-E"?a.net:0);
  const assets=sumBy(accs,a=>cat(a.ruleId)==="BS-A"?a.net:0);
  const equity=Math.abs(sumBy(accs,a=>cat(a.ruleId)==="BS-E"?-a.net:0));
  const profit=rev-exp;
  const bases={revenue:rev,assets:assets,equity:equity,profit:profit};
  let base=bases[basis]||0, usedBasis=basis;
  if(base<=0){ if(bases.revenue>0){base=bases.revenue;usedBasis="revenue";}
    else if(bases.assets>0){base=bases.assets;usedBasis="assets";}
    else {base=sumBy(accs,a=>a.debit);usedBasis="assets";} }
  const value=base*(pct/100);
  return {basis:usedBasis,basisLabel:MAT_BASES[usedBasis],base,pct,value,
          performance:value*0.75,trivial:value*0.05,
          totals:{rev,exp,assets,equity,profit}};
}

/* ---------- الفحوص الأولية الحتمية ---------- */
function runPrechecks(accs,entity){
  const out=[]; const t=tbTotals(accs);
  const has=id=>accs.some(a=>a.ruleId===id);
  const namesOf=id=>accs.filter(a=>a.ruleId===id).map(a=>a.name);
  if(Math.abs(t.diff)>0.5)
    out.push({sev:"crit",title:"الميزان غير متوازن",detail:`إجمالي المدين ${fmt(t.dr)} وإجمالي الدائن ${fmt(t.cr)} والفرق ${fmt(t.diff)}. لا يمكن الاعتماد على الميزان قبل تسوية الفرق.`,refs:["ISA 500"]});
  else
    out.push({sev:"ok",title:"الميزان متوازن",detail:`إجمالي المدين يساوي إجمالي الدائن: ${fmt(t.dr)}.`,refs:[]});
  const un=accs.filter(a=>!a.ruleId);
  if(un.length)
    out.push({sev:"warn",title:`حسابات غير مصنفة (${un.length})`,detail:"تعذر ربطها آليًا بالمعايير وستُعرض على المراجع الذكي للفصل فيها: "+un.slice(0,8).map(a=>a.name).join("، ")+(un.length>8?"…":""),refs:[]});
  const abn=[];
  accs.forEach(a=>{
    const r=ruleById(a.ruleId);
    if(!r||r.nature==="any"||Math.abs(a.net)<0.5) return;
    if(r.nature==="debit"&&a.net<0) abn.push(`${a.name} (دائن ${fmt(-a.net)} وطبيعته مدينة)`);
    if(r.nature==="credit"&&a.net>0) abn.push(`${a.name} (مدين ${fmt(a.net)} وطبيعته دائنة)`);
  });
  if(abn.length)
    out.push({sev:"warn",title:`أرصدة عكس طبيعتها (${abn.length})`,detail:abn.slice(0,6).join("؛ ")+(abn.length>6?"…":""),refs:["ISA 315"]});
  if(has("rentexp")&&!has("rou")&&!has("leaseliab"))
    out.push({sev:"warn",title:"مؤشر عدم تطبيق IFRS 16",detail:"يوجد مصروف إيجار ("+namesOf("rentexp").join("، ")+") دون أصول حق استخدام أو التزامات إيجار. يلزم فحص العقود: قد يتعين رسملة أصل والتزام ما لم تنطبق إعفاءات قصر المدة أو انخفاض القيمة.",refs:["IFRS 16"]});
  if(has("ar")&&!has("ecl"))
    out.push({sev:"warn",title:"ذمم مدينة دون مخصص خسائر ائتمانية",detail:"يتطلب IFRS 9 مخصص خسائر ائتمانية متوقعة للذمم التجارية ولو بالنهج المبسّط، ولم يُرصد حساب مخصص.",refs:["IFRS 9"]});
  if(has("payroll")&&!has("eosb"))
    out.push({sev:"warn",title:"رواتب دون التزام نهاية خدمة",detail:"وجود تكاليف موظفين دون التزام مكافأة نهاية الخدمة مؤشر نقص إثبات وفق IAS 19 ونظام العمل السعودي.",refs:["IAS 19"]});
  if(!has("zakat"))
    out.push({sev:"warn",title:"لا يوجد مخصص زكاة",detail:"المنشآت الخاضعة لأنظمة المملكة يلزمها احتساب مخصص الزكاة وفق المعيار السعودي المعدل ولوائح هيئة الزكاة والضريبة والجمارك.",refs:["معيار الزكاة","لوائح ZATCA"]});
  if(has("reln"))
    out.push({sev:"info",title:"أرصدة أطراف ذات علاقة",detail:namesOf("reln").join("، ")+". تخضع لإفصاحات IAS 24 وإجراءات ISA 550 ورأي لجنة المعايير في معاملات المالك.",refs:["IAS 24","ISA 550"]});
  accs.forEach(a=>{ if(a.ruleId==="cash"&&a.net<-0.5)
    out.push({sev:"warn",title:"رصيد بنكي دائن",detail:`${a.name} برصيد دائن ${fmt(-a.net)}: يُعاد تبويبه سحبًا على المكشوف ضمن الالتزامات المتداولة ولا يُقاصّ مع النقد إلا بشروط IAS 32.`,refs:["IAS 1","IAS 32"]}); });
  const hasRev=accs.some(a=>{const r=ruleById(a.ruleId);return r&&r.st==="PL-R";});
  const hasCogs=has("cogs");
  if(hasRev&&!hasCogs&&has("inv"))
    out.push({sev:"info",title:"إيراد ومخزون دون تكلفة مبيعات",detail:"وجود مبيعات ومخزون دون حساب تكلفة قد يشير إلى عدم إقفال التكلفة أو خطأ تبويب.",refs:["IAS 2"]});
  if(has("depexp")&&!has("accdep"))
    out.push({sev:"info",title:"مصروف استهلاك دون مجمع",detail:"يوجد مصروف استهلاك دون حساب مجمع استهلاك في الميزان؛ يُتحقق من العرض.",refs:["IAS 16"]});
  if(has("bio"))
    out.push({sev:"info",title:"أصول حيوية",detail:"تُقاس بالقيمة العادلة ناقصًا تكاليف البيع وفق IAS 41 مع الإفصاح عن التحركات والافتراضات.",refs:["IAS 41","IFRS 13"]});
  return out;
}

