function tbPromptTable(accs){
  const head="الرمز | اسم الحساب | مدين | دائن | التصنيف الآلي والمعايير";
  const lines=accs.map(a=>{
    const r=ruleById(a.ruleId);
    const cls=r?`${r.label} ← ${r.stds.map(s=>s.ref).join("، ")}`:"غير مصنف";
    return `${a.code} | ${a.name} | ${a.debit?fmt(a.debit):"-"} | ${a.credit?fmt(a.credit):"-"} | ${cls}`;
  });
  return head+"\n"+lines.join("\n");
}
function buildRound1Prompt(entity,accs,pre,mat){
  const t=tbTotals(accs);
  const preTxt=pre.map(p=>`- [${p.sev==="crit"?"حرج":p.sev==="warn"?"تنبيه":p.sev==="ok"?"سليم":"معلومة"}] ${p.title}: ${p.detail}`).join("\n");
  return `هذه الجولة الأولى من مراجعة متعددة الجولات.
أولًا: ميزان المراجعة (إجمالي المدين ${fmt(t.dr)} | إجمالي الدائن ${fmt(t.cr)}):
${tbPromptTable(accs)}

ثانيًا: نتائج الفحص الأولي الآلي:
${preTxt}

ثالثًا: الأهمية النسبية المبدئية وفق ISA 320: الأساس ${mat.basisLabel} (${fmt(mat.base)}) بنسبة ${mat.pct}% = ${fmt(mat.value)}، وأهمية الأداء ${fmt(mat.performance)}، وحد التافه ${fmt(mat.trivial)}.

المطلوب في هذه الجولة:
1) راجع تصنيف كل حساب وصحح أو أضف ربط المعايير في account_standards (خاصة الحسابات غير المصنفة).
2) حدد الملاحظات والمخاطر الأولية في findings مع مرجع المعيار ومبلغ تقديري إن أمكن.
3) اطلب المستندات اللازمة للجولة التالية في document_requests مرتبةً بالأولوية، وأسئلتك للإدارة في questions_to_management.
4) حدد status: اجعلها needs_documents ما دمت تحتاج أدلة، ولا تجعلها ready_to_conclude إلا إذا اكتفيت.
أخرج JSON فقط بهذا المخطط:
${SCHEMA_ROUND}`;
}
function buildFollowupPrompt(roundNo,answers,notes,fileNames,skipped){
  let s=`هذه الجولة رقم ${roundNo}. تجد أدناه ردود الإدارة والمستندات المرفوعة استجابةً لطلباتك السابقة.\n`;
  if(answers&&answers.length) s+="\nإجابات الإدارة على الأسئلة:\n"+answers.map(a=>`- ${a.q}\n  الجواب: ${a.a||"(لم يُجب)"}`).join("\n");
  if(notes) s+="\n\nملاحظات إضافية من المستخدم:\n"+notes;
  if(fileNames&&fileNames.length) s+="\n\nالمستندات المرفقة في هذه الرسالة: "+fileNames.join("، ");
  if(skipped&&skipped.length) s+="\n\nطلبات تعذر توفيرها حاليًا: "+skipped.join("، ")+" — قوِّم الأثر وقرر البديل وفق ISA 500.";
  s+=`\n\nالمطلوب: افحص المستندات فحص مراجعٍ ناقد (تحقق من الاتساق الحسابي والتواريخ والأطراف ومطابقتها بأرصدة الميزان)، وحدّث الملاحظات، واطلب ما يلزم إضافيًا أو أعلن الاكتفاء عبر status=ready_to_conclude.\nأخرج JSON فقط بمخطط الجولة نفسه:\n${SCHEMA_ROUND}`;
  return s;
}
function buildFinalPrompt(mat){
  return `اختُتمت جولات جمع الأدلة. أصدر الآن مخرجات المراجعة النهائية كاملةً بالعربية المهنية اعتمادًا على كل ما سبق في هذه المحادثة.
اشترط في قيود التسوية توازن كل قيد (مجموع المدين = مجموع الدائن) وبيان مرجع المعيار وسببه، وميّز التسويات عن إعادات التبويب. قارن أثر التحريفات المجمعة بالأهمية النسبية (${fmt(mat.value)}) عند تحديد opinion_indication، واذكر في unresolved كل ما لم يُحسم وأثره.
أخرج JSON فقط بهذا المخطط:
${SCHEMA_FINAL}`;
}
function safeParseJson(text){
  if(!text) return null;
  let t=String(text).trim();
  t=t.replace(/^```(?:json)?\s*/i,"").replace(/```\s*$/,"").trim();
  const a=t.indexOf("{"), b=t.lastIndexOf("}");
  if(a===-1||b<=a) return null;
  let body=t.slice(a,b+1);
  try{ return JSON.parse(body); }catch(e){}
  try{ return JSON.parse(body.replace(/,\s*([}\]])/g,"$1")); }catch(e){ return null; }
}

