/* ---------- استدعاء Gemini ---------- */
async function callGemini(contents,{system,json=true,tools=null,maxTokens=8192}={}){
  const url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(getModel())}:generateContent?key=${encodeURIComponent(getKey())}`;
  const body={contents,generationConfig:{temperature:0.2,maxOutputTokens:maxTokens}};
  if(system) body.systemInstruction={parts:[{text:system}]};
  if(json) body.generationConfig.responseMimeType="application/json";
  if(tools) body.tools=tools;
  const res=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});
  if(!res.ok){ let msg="HTTP "+res.status; try{const e=await res.json(); if(e.error&&e.error.message) msg=e.error.message;}catch(_){}
    if(res.status===400&&/API key/i.test(msg)) msg="المفتاح غير صالح — تحقق منه في الإعدادات";
    if(res.status===429) msg="تجاوزت حد الاستخدام مؤقتًا — انتظر دقيقة ثم أعد المحاولة";
    throw new Error(msg); }
  const data=await res.json();
  const cand=(data.candidates||[])[0];
  if(!cand) throw new Error("لم يصل رد من النموذج"+(data.promptFeedback&&data.promptFeedback.blockReason?" (حُجب: "+data.promptFeedback.blockReason+")":""));
  const text=((cand.content||{}).parts||[]).map(p=>p.text||"").join("");
  return {text,data};
}
function guessMime(name){ const e=name.toLowerCase().split(".").pop();
  return {pdf:"application/pdf",png:"image/png",jpg:"image/jpeg",jpeg:"image/jpeg",webp:"image/webp",gif:"image/gif",heic:"image/heic"}[e]||null; }
async function fileToParts(f){
  const name=f.name, lower=name.toLowerCase();
  if(/\.(txt|csv|tsv|md|json|xml)$/.test(lower)){
    const t=await f.text();
    return [{text:`\n=== مستند نصي: ${name} ===\n${t.slice(0,200000)}\n=== نهاية ${name} ===`}];
  }
  if(/\.xlsx?$/.test(lower)){
    await ensureXLSX();
    const wb=XLSX.read(await f.arrayBuffer(),{type:"array"});
    let out=`\n=== جداول من ملف: ${name} ===`;
    wb.SheetNames.slice(0,6).forEach(sn=>{ out+=`\n-- ورقة ${sn} --\n`+XLSX.utils.sheet_to_csv(wb.Sheets[sn],{FS:"\t"}).slice(0,120000); });
    return [{text:out+`\n=== نهاية ${name} ===`}];
  }
  const mime=f.type||guessMime(name);
  if(!mime) throw new Error(`صيغة غير مدعومة: ${name} — المدعوم: PDF وصور و CSV/TXT و Excel`);
  const b64=await new Promise((res,rej)=>{ const r=new FileReader();
    r.onload=()=>res(String(r.result).split(",")[1]); r.onerror=()=>rej(new Error("تعذر قراءة "+name)); r.readAsDataURL(f); });
  return [{inline_data:{mime_type:mime,data:b64}}];
}
function historyContents(){
  const out=[];
  state.chat.forEach(m=>{
    const parts=[{text:m.text}];
    if(m.role==="user"&&resendDocs()&&sessionDocs[m.round]) parts.push(...sessionDocs[m.round]);
    out.push({role:m.role,parts});
  });
  return out;
}

